r=Path.cwd();b=r/'evidence/01_PT/018_NK-OPS-001';patchfile=b/'evidence/PG30988-ssc352-scenario-staging-design-only-patch-v1/design-only-main-patch.json';v=json.loads(patchfile.read_text());w=r.parent/'ssc352-scenario-staging-design-20261114';private=r.parent/'pgpt-runs/PG379/pg30990-ssc352-design';e=b/'evidence/PG30990-ssc352-design-main-publication-v1';assert not (e/'manifest.json').exists();private.mkdir(mode=0o700,exist_ok=True);e.mkdir(exist_ok=True)
