names=[x for x in run(['git','diff','--name-only','-z'],w).split('\0') if x];assert set(names)==set(v['paths']);run(['git','diff','--check'],w);run(['git','add','--',*v['paths']],w);run(['git','commit','-m','docs(ssc352): define borrowed standard JDBC staging contract'],w);head=run(['git','rev-parse','HEAD'],w);run(['git','push','-u','origin',branch],w)
